    uint256 internal constant REVIEW_GLOBAL_DAILY_POINTS = 50_000;

    uint256 internal constant ACTIVATE_GLOBAL_DAILY_POINTS = 100_000;

    uint256 internal constant GAME_GLOBAL_DAILY_POINTS = 50_000;

